from typing import List, Tuple

def num_behaviours(num_states: int, num_observations: int) -> int:
    """Cardinality of the behaviour space |S -> B| = |B|^|S|."""
    return num_observations ** num_states

def blind_spot_exact_bound(num_states: int, num_observations: int) -> int:
    """Guaranteed blind-spot size |S->B| - |S|."""
    return num_behaviours(num_states, num_observations) - num_states

def counting_table(max_states: int = 8) -> None:
    print(f"{'|S|':>4} {'|B|':>4} {'|B|^|S|':>12} {'blind spot >=':>14}")
    for m in range(1, max_states):
        for b in (2, 3):
            print(f"{m:>4} {b:>4} {num_behaviours(m,b):>12} "
                  f"{blind_spot_exact_bound(m,b):>14}")

if __name__ == "__main__":
    counting_table()

from typing import List, Tuple

def injective_self_model(num_states: int, num_observations: int) -> List[Tuple[int, ...]]:
    """Encode state index i as its base-b digits across |S| slots, giving an
    injective inspection map: distinct states -> distinct internal models."""
    out: List[Tuple[int, ...]] = []
    for i in range(num_states):
        digits, x = [], i
        for _ in range(num_states):
            digits.append(x % num_observations); x //= num_observations
        out.append(tuple(digits))
    return out

if __name__ == "__main__":
    model = injective_self_model(4, 2)
    for i, row in enumerate(model):
        print(f"state {i}: {row}")
    print("all distinct?", len(set(model)) == len(model))  # True

