def blind_spot_size(m: int, b: int) -> tuple[int, int]:
    """Return (guaranteed blind spot b^m - m, universal bound 2^m - m)."""
    assert b >= 2, "need at least two observations"
    total = b ** m
    return (total - m, 2 ** m - m)

